    fn test_list_tags_fetches_unfiltered_and_filters_locally_with_globset() {
        let runner = FakeRunner {
            calls: Mutex::new(Vec::new()),
            response: Box::new(|_args| Ok(ok("pkg-a@1.0.0\npkg-ab@1.0.0\nunrelated\n"))),
